import React, { useState, useEffect, useRef, useMemo, useCallback, useReducer, createContext, useContext, Component } from 'react';

function Logger({ config }) {
  useEffect(() => {
    window.__fires = (window.__fires || 0) + 1;
    const el = document.getElementById('fires');
    if (el) el.textContent = String(window.__fires);
  }, [config]);
  return null;
}

function App() {
  const [count, setCount] = useState(0);
  const config = { level: 'info' };

  return (
    <div>
      <p id="fires">0</p>
      <p id="count">Count: {count}</p>
      <button id="inc" onClick={() => setCount(count + 1)}>+</button>
      <Logger config={config} />
    </div>
  );
}

export default App;

