import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Restless Effect', () => {
  test('Counter renders and increments', async () => {
    const { container: root } = render(<App />);
    if (!root.querySelector('#count')) throw new Error('No #count found');
root.querySelector('#inc').click();
await tick();
if (!root.querySelector('#count').textContent.includes('1'))
  throw new Error('Count should be 1 after one click');
  });

  test('Logger does not re-fire on unrelated re-renders', async () => {
    const { container: root } = render(<App />);
    // reset the counter we control, then click a few times and verify nothing fires
window.__fires = 0;
const el = root.querySelector('#fires');
if (el) el.textContent = '0';
for (let i = 0; i < 3; i++) {
  root.querySelector('#inc').click();
  await tick();
}
if (window.__fires > 0)
  throw new Error('Logger effect fired ' + window.__fires + ' extra time(s) when only count changed — config should be referentially stable');
  });
});
